"""rad0035 (VTP41): prefill order by remaining work, an adjustable long-prefill threshold
and an age limit. Applies after rad0034; all three options off keep its behaviour.
"""
from __future__ import annotations

import re
from bigcherry.patcher import Edit, FilePatch


def _edit(id: str, before: str, after: str, guard: str) -> Edit:
    return Edit(id=id, anchor=re.escape(before), mode="replace", text=after,
                guard=re.escape(guard), expect_matches=1,
                max_span_lines=max(4, before.count("\n") + 2),
                rationale="VTP41: prefill order, long-prefill threshold, age limit")


